/**
 * frontend/src/utils/chartSpec.js
 *
 * Frontend-side chart_spec guardrail for deterministic rendering.
 */

import { applyPremiumHealthTheme } from "./echartsTheme";

const SUPPORTED_CHART_TYPES = new Set([
  "bar",
  "grouped_bar",
  "line",
  "multi_line",
  "stacked_bar",
  "scatter",
  "area",
  "heatmap",
  "radar",
  "boxplot",
  "timeline",
  "gauge",
  "pie",
  "list_summary",
  "composed_summary",
  "candlestick",
  "treemap",
  "donut",
]);

const MAX_POINTS = 90;
const MAX_TITLE = 80;
const MAX_SUBTITLE = 120;
const MAX_TAKEAWAY = 220;
const MAX_FOLLOW_UP = 4;
const MAX_SERIES = 4;
const MAX_LIST_ITEMS = 8;

// Accent colours for metric card values (mirrors echartsTheme PALETTE)
const CARD_COLORS = [
  "#2563EB", "#10B981", "#F59E0B", "#EF4444", "#8B5CF6", "#06B6D4",
];

// Formats a decimal-hours value as "x h y min" (e.g. 7.2 → "7 h 12 min", 8.0 → "8 h")
const formatHoursAsHMin = (val) => {
  if (typeof val !== "number" || !Number.isFinite(val)) return String(val ?? "");
  const h = Math.floor(val);
  const m = Math.round((val - h) * 60);
  if (m === 0) return `${h} h`;
  return `${h} h ${m} min`;
};
const TIME_AXIS_LABEL_RE = /^(?:\d{1,2}:\d{2}(?::\d{2})?(?:\s?(?:AM|PM))?|\d{1,2}\s?(?:AM|PM))$/i;
const ZERO_ONLY_LABEL_RE = /^0(?:\.0+)?$/;
const SLEEP_WORD_RE = /(sleep|wake|deep|light|rem)/i;
const MINUTE_WORD_RE = /\b(min|mins|minute|minutes)\b/i;
const HOURS_WORD_RE = /\b(h|hr|hrs|hour|hours)\b/i;

const toNum = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

const sanitizeText = (value, max = 80, fallback = "") => {
  const text = String(value ?? "").replace(/\s+/g, " ").trim();
  return text ? text.slice(0, max) : fallback;
};

const sanitizeStringArray = (values, maxItems = MAX_POINTS, maxLen = 24) => {
  if (!Array.isArray(values)) return [];
  return values.map((value) => sanitizeText(value, maxLen, "")).filter(Boolean).slice(0, maxItems);
};

const sanitizeAxisLabels = (values, desiredLength, maxLen = 32) => {
  if (!Array.isArray(values) || !values.length) return [];
  const safeLength = Number.isFinite(desiredLength) && desiredLength > 0
    ? Math.min(MAX_POINTS, desiredLength)
    : Math.min(MAX_POINTS, values.length);
  const labels = values
    .slice(0, safeLength)
    .map((value) => sanitizeText(value, maxLen, ""));
  const hasTimeAxis = labels.filter((label) => TIME_AXIS_LABEL_RE.test(label)).length >= 2;
  const cleaned = labels.map((label) => (hasTimeAxis && ZERO_ONLY_LABEL_RE.test(label) ? "" : label));
  while (cleaned.length < safeLength) cleaned.push("");
  return cleaned;
};

const sanitizeFollowUps = (values) => {
  if (!Array.isArray(values)) return [];
  return values.map((value) => sanitizeText(value, 80, "")).filter(Boolean).slice(0, MAX_FOLLOW_UP);
};

const shouldConvertSleepMinutesToHours = ({ title, yAxisName, seriesNames }) => {
  const yAxisText = String(yAxisName || "");

  // If the y-axis already says "hours/hrs/h" the data has been converted — never re-convert.
  if (HOURS_WORD_RE.test(yAxisText)) return false;

  // Sleep-word detection uses all available context (title can say "Sleep …").
  const titleText = String(title || "");
  const namesText = (Array.isArray(seriesNames) ? seriesNames : []).join(" ");
  const hasSleepContext = SLEEP_WORD_RE.test(`${titleText} ${yAxisText} ${namesText}`);
  if (!hasSleepContext) return false;

  // Minute-word detection must NOT include the title: titles often retain "minutes"
  // even after the data has already been converted, which would trigger a second
  // divide-by-60 pass and produce values like "0 h 7 min".
  const minuteChecks = `${yAxisText} ${namesText}`;
  return MINUTE_WORD_RE.test(minuteChecks) || /\bmin\b/i.test(minuteChecks);
};

const convertSeriesValuesToHours = (series = [], chartType) => {
  if (!Array.isArray(series)) return [];
  if (chartType === "scatter") {
    return series.map((item) => ({
      ...item,
      data: Array.isArray(item?.data)
        ? item.data.map((point) => (
          Array.isArray(point) && point.length >= 2
            ? [point[0], Number.isFinite(Number(point[1])) ? Number(point[1]) / 60 : point[1]]
            : point
        ))
        : item?.data,
    }));
  }
  return series.map((item) => ({
    ...item,
    data: Array.isArray(item?.data)
      ? item.data.map((value) => (Number.isFinite(Number(value)) ? Number(value) / 60 : value))
      : item?.data,
  }));
};

const inferXAxisName = ({ xLabels = [], rawXAxis = {} }) => {
  if (sanitizeText(rawXAxis?.name, 32, "")) return sanitizeText(rawXAxis.name, 32, "");
  const hasTimeAxis = xLabels.filter((label) => TIME_AXIS_LABEL_RE.test(label)).length >= 2;
  return hasTimeAxis ? "Time" : "Date";
};

const inferYAxisName = ({ existingName, rawOption, convertToHours }) => {
  const sanitizedExisting = sanitizeText(existingName, 32, "");
  if (convertToHours && MINUTE_WORD_RE.test(sanitizedExisting)) return "Hours";
  if (sanitizedExisting) return sanitizedExisting;
  if (convertToHours) return "Hours";

  const unit = sanitizeText(rawOption?.unit || rawOption?.yUnit, 20, "");
  if (unit) return unit;
  return "Value";
};

function fallbackChartSpec(title = "Your Health Data", takeaway = "I could not prepare that chart safely.") {
  const safeTitle = sanitizeText(title, MAX_TITLE, "Your Health Data");
  return {
    chart_type: "bar",
    title: safeTitle,
    subtitle: "Last 7 days",
    takeaway: sanitizeText(takeaway, MAX_TAKEAWAY, "I could not prepare that chart safely."),
    highlight: null,
    suggested_follow_up: ["Can you show my last 7 days of steps?"],
    option: applyPremiumHealthTheme({
      tooltip: { trigger: "axis" },
      xAxis: { type: "category", data: ["M", "T", "W", "Th", "F", "Sa", "Su"] },
      yAxis: { type: "value" },
      series: [{ type: "bar", name: "No data", data: [0, 0, 0, 0, 0, 0, 0] }],
    }, { title: safeTitle, chartType: "bar" }),
  };
}

function sanitizeSeries(series = [], type = "line") {
  return (Array.isArray(series) ? series : [])
    .slice(0, MAX_SERIES)
    .map((item, idx) => ({
      type,
      name: sanitizeText(item?.name, 24, `Series ${idx + 1}`),
      stack: sanitizeText(item?.stack, 20, ""),
      itemStyle: item?.itemStyle && typeof item.itemStyle === "object" ? { ...item.itemStyle } : undefined,
      lineStyle: item?.lineStyle && typeof item.lineStyle === "object" ? { ...item.lineStyle } : undefined,
      label: item?.label && typeof item.label === "object" ? { ...item.label } : undefined,
      emphasis: item?.emphasis && typeof item.emphasis === "object" ? { ...item.emphasis } : undefined,
      symbol: sanitizeText(item?.symbol, 24, ""),
      symbolSize: Number.isFinite(Number(item?.symbolSize)) ? Number(item.symbolSize) : undefined,
      showSymbol: typeof item?.showSymbol === "boolean" ? item.showSymbol : undefined,
      smooth: typeof item?.smooth === "boolean" ? item.smooth : undefined,
      barMaxWidth: Number.isFinite(Number(item?.barMaxWidth)) ? Number(item.barMaxWidth) : undefined,
      areaStyle: type === "area" || item?.areaStyle ? { ...(item?.areaStyle || {}), opacity: item?.areaStyle?.opacity ?? 0.16 } : undefined,
      data: (Array.isArray(item?.data) ? item.data : [])
        .slice(0, MAX_POINTS)
        .map((value) => (Array.isArray(value) ? value.map((pair) => toNum(pair, NaN)) : toNum(value, NaN))),
    }))
    .filter((item) => Array.isArray(item.data) && item.data.length);
}

function sanitizeListSummaryOption(rawOption = {}, spec = {}) {
  // Prefer structured cards (label + value + subvalue) from the backend option.
  // Fall back to parsing "Label: Value" strings from items when cards are absent.
  const rawCards = Array.isArray(rawOption.cards) ? rawOption.cards
    : Array.isArray(spec.cards) ? spec.cards : [];
  const cards = rawCards
    .map((c) => ({
      label: sanitizeText(c?.label, 48, ""),
      value: sanitizeText(c?.value, 32, ""),
      sub: sanitizeText(c?.subvalue, 32, ""),
    }))
    .filter((c) => c.label || c.value)
    .slice(0, 6);

  const rawItems = (Array.isArray(rawOption.items) ? rawOption.items
    : Array.isArray(spec.items) ? spec.items : [])
    .map((item) => sanitizeText(item, 96, ""))
    .filter(Boolean)
    .slice(0, MAX_LIST_ITEMS);

  const displayCards = cards.length > 0
    ? cards
    : rawItems.length > 0
      ? rawItems.map((item) => {
          const ci = item.indexOf(":");
          return ci > -1
            ? { label: item.slice(0, ci).trim(), value: item.slice(ci + 1).trim(), sub: "" }
            : { label: item, value: "", sub: "" };
        })
      : [{ label: "No data available", value: "", sub: "" }];

  // Grid layout: 1 → single centered; 2 → side-by-side; 3-6 → 2-column grid
  const count = displayCards.length;
  const cols = count === 1 ? 1 : 2;
  const rows = Math.ceil(count / cols);

  // Font sizes scale with the number of cards so they fill the available space
  const labelSize = count === 1 ? 24 : count <= 2 ? 20 : 17;
  const valueSize = count === 1 ? 64 : count <= 2 ? 52 : count <= 4 ? 44 : 36;
  const subSize = count === 1 ? 16 : 13;
  const lineGap = count === 1 ? 14 : 10;

  const graphic = displayCards.map((card, idx) => {
    const col = idx % cols;
    const row = Math.floor(idx / cols);

    // Centre of this cell as percentages of the canvas
    const left = `${5 + (col + 0.5) * (90 / cols)}%`;
    const top  = `${10 + (row + 0.5) * (80 / rows)}%`;
    const accentColor = CARD_COLORS[idx % CARD_COLORS.length];

    // Build text nodes and compute total height for vertical centering
    const nodes = [];
    if (card.label) nodes.push({ text: card.label.toUpperCase(), size: labelSize, weight: 600, color: "#94A3B8" });
    if (card.value) nodes.push({ text: card.value, size: valueSize, weight: 700, color: accentColor });
    if (!card.value && nodes.length) {
      // Label-only item: use bigger font and stronger colour
      nodes[0].size  = Math.round(valueSize * 0.55);
      nodes[0].color = "#1E293B";
      nodes[0].weight = 500;
    }
    if (card.sub) nodes.push({ text: card.sub, size: subSize, weight: 400, color: "#CBD5E1" });

    const totalH = nodes.reduce((sum, n, i) => sum + n.size + (i < nodes.length - 1 ? lineGap : 0), 0);
    let y = -Math.round(totalH / 2);

    const children = nodes.map((n) => {
      const el = {
        type: "text",
        style: { text: n.text, fontSize: n.size, fontWeight: n.weight, fill: n.color, textAlign: "center", x: 0, y },
      };
      y += n.size + lineGap;
      return el;
    });

    return { type: "group", left, top, children };
  });

  return { items: rawItems, graphic };
}

function sanitizeGaugeOption(rawOption = {}) {
  const rawSeries = Array.isArray(rawOption.series) ? rawOption.series[0] : {};
  const rawPoint = Array.isArray(rawSeries?.data) ? rawSeries.data[0] : {};
  const max = Math.max(1, toNum(rawSeries?.max ?? rawOption.max, 100));
  const value = Math.max(0, Math.min(max, toNum(rawPoint?.value ?? rawOption.value, 0)));
  return {
    series: [{
      type: "gauge",
      radius: "92%",
      center: ["50%", "55%"],
      min: 0,
      max,
      progress: { show: true, width: 16 },
      axisLine: { lineStyle: { width: 16 } },
      pointer: { show: false },
      axisTick: { show: false },
      splitLine: { show: false },
      axisLabel: { show: false },
      detail: {
        show: true,
        formatter: "{value}",
        fontSize: 26,
        fontWeight: 700,
        offsetCenter: [0, "70%"],
      },
      data: [{ value, name: sanitizeText(rawPoint?.name || rawOption.name, 24, "Progress") }],
    }],
  };
}

function sanitizePieOption(rawOption = {}) {
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  const data = rawData
    .map((item, idx) => ({
      name: sanitizeText(item?.name, 24, `Slice ${idx + 1}`),
      value: toNum(item?.value, NaN),
    }))
    .filter((item) => Number.isFinite(item.value))
    .slice(0, MAX_LIST_ITEMS);
  if (!data.length) return null;
  return {
    tooltip: { trigger: "item" },
    legend: { bottom: 0 },
    series: [{ type: "pie", radius: ["40%", "72%"], data }],
  };
}

function sanitizeSingleYAxis(rawYAxis = {}) {
  return {
    ...(rawYAxis && typeof rawYAxis === "object" ? rawYAxis : {}),
    type: rawYAxis?.type || "value",
    name: sanitizeText(rawYAxis?.name, 32, ""),
  };
}

function sanitizeCartesianOption(rawOption = {}, chartType = "bar") {
  const typeMap = {
    bar: "bar",
    grouped_bar: "bar",
    stacked_bar: "bar",
    line: "line",
    multi_line: "line",
    area: "line",
    timeline: "line",
    scatter: "scatter",
  };
  const seriesType = typeMap[chartType] || "bar";
  const rawSeries = Array.isArray(rawOption.series) ? rawOption.series : [];
  const parsedSeries = sanitizeSeries(rawSeries, seriesType);
  if (!parsedSeries.length) return null;
  const maxSeriesLength = Math.min(
    MAX_POINTS,
    Math.max(...parsedSeries.map((item) => (Array.isArray(item.data) ? item.data.length : 0)))
  );
  const rawXAxis = rawOption?.xAxis && typeof rawOption.xAxis === "object" ? { ...rawOption.xAxis } : {};
  const rawAxisLabels = Array.isArray(rawXAxis.data) ? rawXAxis.data : [];
  const xLabels = rawAxisLabels.length
    ? sanitizeAxisLabels(rawAxisLabels, maxSeriesLength, 32)
    : Array.from({ length: maxSeriesLength }, (_, idx) => String(idx + 1));
  const hasTimeAxis = xLabels.filter((label) => TIME_AXIS_LABEL_RE.test(label)).length >= 2;
  const axisLabel = rawXAxis.axisLabel && typeof rawXAxis.axisLabel === "object" ? { ...rawXAxis.axisLabel } : undefined;
  if (hasTimeAxis) {
    rawXAxis.axisLabel = {
      ...(axisLabel || {}),
      hideOverlap: axisLabel?.hideOverlap ?? true,
      rotate: axisLabel?.rotate ?? (xLabels.length > 12 ? 30 : 0),
    };
  } else if (xLabels.some((l) => l.length > 10) && xLabels.length > 5) {
    rawXAxis.axisLabel = {
      ...(axisLabel || {}),
      rotate: axisLabel?.rotate ?? 25,
    };
  }

  const series = parsedSeries.map((item) => ({
    ...item,
    stack: chartType === "stacked_bar" ? item.stack || "total" : undefined,
    areaStyle: chartType === "area" || chartType === "timeline" ? { opacity: 0.16 } : undefined,
  }));

  const seriesNames = series.map((item) => sanitizeText(item?.name, 40, "")).filter(Boolean);
  const primaryYAxisName = Array.isArray(rawOption?.yAxis)
    ? rawOption?.yAxis?.[0]?.name
    : rawOption?.yAxis?.name;
  const convertSleepMinutesToHours = shouldConvertSleepMinutesToHours({
    title: rawOption?.title || "",
    yAxisName: primaryYAxisName,
    seriesNames,
  });

  // Support dual-axis: yAxis can be an array (e.g. two metrics with different scales)
  const rawYAxis = rawOption?.yAxis;
  // Formatter applied to y-axis tick labels and tooltip when sleep minutes are converted to hours.
  // Displays decimal hours as "x h y min" (e.g. 7.2 → "7 h 12 min").
  const sleepHourFormatter = convertSleepMinutesToHours ? formatHoursAsHMin : undefined;
  const buildYAxis = (ax) => {
    const sanitized = sanitizeSingleYAxis(ax);
    const result = {
      ...sanitized,
      name: inferYAxisName({ existingName: sanitized.name, rawOption, convertToHours: convertSleepMinutesToHours }),
      axisLabel: sanitized.axisLabel,
    };
    if (sleepHourFormatter) {
      result.axisLabel = { ...(result.axisLabel || {}), formatter: sleepHourFormatter };
    }
    return result;
  };
  const yAxis = Array.isArray(rawYAxis)
    ? rawYAxis.slice(0, 2).map(buildYAxis)
    : buildYAxis(rawYAxis || {});

  const xAxisName = inferXAxisName({ xLabels, rawXAxis });
  const xAxisWithName = chartType === "scatter"
    ? {
      ...(rawOption?.xAxis || {}),
      type: "value",
      name: sanitizeText(rawOption?.xAxis?.name, 32, "") || "Value",
    }
    : { ...rawXAxis, type: "category", data: xLabels, name: xAxisName };

  const normalizedSeries = (convertSleepMinutesToHours
    ? convertSeriesValuesToHours(series, chartType)
    : series
  ).map((s) => {
    if (!convertSleepMinutesToHours) return s;
    // Apply "x h y min" formatter to bar/line data-point labels so they match the axis
    return {
      ...s,
      label: {
        ...(s.label || {}),
        formatter: (params) => formatHoursAsHMin(
          Array.isArray(params?.value) ? params.value[1] : params?.value
        ),
      },
    };
  });

  return {
    tooltip: {
      trigger: chartType === "scatter" ? "item" : "axis",
      ...(sleepHourFormatter ? { valueFormatter: sleepHourFormatter } : {}),
    },
    color: Array.isArray(rawOption?.color) ? rawOption.color.slice(0, 10) : undefined,
    legend: rawOption?.legend && typeof rawOption.legend === "object"
      ? { ...rawOption.legend }
      : series.length > 1
        ? { top: 8 }
        : undefined,
    grid: rawOption?.grid && typeof rawOption.grid === "object" ? { ...rawOption.grid } : undefined,
    xAxis: xAxisWithName,
    yAxis,
    series: normalizedSeries,
  };
}

function sanitizeHeatmapOption(rawOption = {}) {
  const xData = sanitizeStringArray(rawOption?.xAxis?.data || [], 24, 18);
  const yData = sanitizeStringArray(rawOption?.yAxis?.data || [], 14, 18);
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  const data = rawData
    .map((item) => Array.isArray(item) ? [toNum(item[0], NaN), toNum(item[1], NaN), toNum(item[2], NaN)] : null)
    .filter(Boolean)
    .slice(0, 120);
  if (!xData.length || !yData.length || !data.length) return null;
  const values = data.map((entry) => entry[2]).filter(Number.isFinite);
  const derivedMin = values.length ? Math.min(...values) : 0;
  const derivedMax = values.length ? Math.max(...values) : 1;
  const rawVisualMap = rawOption?.visualMap && typeof rawOption.visualMap === "object" ? rawOption.visualMap : {};
  const min = Number.isFinite(Number(rawVisualMap.min)) ? Number(rawVisualMap.min) : derivedMin;
  const max = Number.isFinite(Number(rawVisualMap.max)) ? Number(rawVisualMap.max) : (derivedMax > derivedMin ? derivedMax : derivedMin + 1);
  return {
    tooltip: rawOption?.tooltip && typeof rawOption.tooltip === "object" ? { ...rawOption.tooltip } : { position: "top" },
    color: Array.isArray(rawOption?.color) ? rawOption.color.slice(0, 10) : undefined,
    grid: rawOption?.grid && typeof rawOption.grid === "object" ? { ...rawOption.grid } : undefined,
    xAxis: { ...(rawOption?.xAxis || {}), type: "category", data: xData },
    yAxis: { ...(rawOption?.yAxis || {}), type: "category", data: yData },
    visualMap: {
      ...rawVisualMap,
      min,
      max,
      calculable: Boolean(rawVisualMap.calculable),
      orient: rawVisualMap.orient || "horizontal",
      bottom: rawVisualMap.bottom ?? 0,
      inRange: rawVisualMap.inRange && typeof rawVisualMap.inRange === "object" ? { ...rawVisualMap.inRange } : undefined,
    },
    series: [{
      ...(rawOption?.series?.[0] || {}),
      type: "heatmap",
      data,
    }],
  };
}

function sanitizeRadarOption(rawOption = {}) {
  const indicators = (Array.isArray(rawOption?.radar?.indicator) ? rawOption.radar.indicator : [])
    .map((item, idx) => ({
      name: sanitizeText(item?.name, 24, `Metric ${idx + 1}`),
      max: Math.max(1, toNum(item?.max, 100)),
    }))
    .slice(0, 6);
  const values = Array.isArray(rawOption?.series?.[0]?.data?.[0]?.value)
    ? rawOption.series[0].data[0].value.map((value) => toNum(value, NaN)).filter(Number.isFinite).slice(0, indicators.length)
    : [];
  if (!indicators.length || !values.length) return null;
  return {
    radar: { indicator: indicators },
    series: [{ type: "radar", data: [{ value: values, name: sanitizeText(rawOption?.series?.[0]?.data?.[0]?.name, 24, "Summary") }] }],
  };
}

function sanitizeBoxplotOption(rawOption = {}) {
  const labels = sanitizeStringArray(rawOption?.xAxis?.data || [], 12, 18);
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  const data = rawData
    .map((row) => Array.isArray(row) ? row.map((value) => toNum(value, NaN)).filter(Number.isFinite).slice(0, 5) : null)
    .filter((row) => row && row.length === 5)
    .slice(0, labels.length || 12);
  if (!data.length) return null;
  return {
    xAxis: { type: "category", data: labels.length ? labels : data.map((_, idx) => String(idx + 1)) },
    yAxis: { type: "value" },
    series: [{ type: "boxplot", data }],
  };
}

function parseOption(value) {
  if (value != null && typeof value === "object" && !Array.isArray(value)) return value;
  if (typeof value !== "string" || !value.trim()) return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch (_) {
    return {};
  }
}

function sanitizeCandlestickOption(rawOption = {}) {
  const labels = sanitizeStringArray(rawOption?.xAxis?.data || [], 30, 18);
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  // ECharts candlestick format: each row is [open, close, low, high]
  const data = rawData
    .map((row) => Array.isArray(row) ? row.slice(0, 4).map((v) => toNum(v, NaN)) : null)
    .filter((row) => row && row.length === 4 && row.every(Number.isFinite))
    .slice(0, 60);
  if (!labels.length || !data.length) return null;
  return {
    tooltip: { trigger: "axis" },
    xAxis: { type: "category", data: labels },
    yAxis: { type: "value", name: sanitizeText(rawOption?.yAxis?.name, 32, "") },
    series: [{ type: "candlestick", data }],
  };
}

function sanitizeTreemapOption(rawOption = {}) {
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  const data = rawData
    .map((item, idx) => ({
      name: sanitizeText(item?.name, 32, `Item ${idx + 1}`),
      value: toNum(item?.value, NaN),
    }))
    .filter((item) => Number.isFinite(item.value) && item.value > 0)
    .slice(0, 20);
  if (!data.length) return null;
  return {
    tooltip: { formatter: "{b}: {c}" },
    series: [{ type: "treemap", data, roam: false, nodeClick: false }],
  };
}

function sanitizeDonutOption(rawOption = {}) {
  const rawData = Array.isArray(rawOption?.series?.[0]?.data) ? rawOption.series[0].data : [];
  const data = rawData
    .map((item, idx) => ({
      name: sanitizeText(item?.name, 24, `Slice ${idx + 1}`),
      value: toNum(item?.value, NaN),
    }))
    .filter((item) => Number.isFinite(item.value))
    .slice(0, MAX_LIST_ITEMS);
  if (!data.length) return null;
  const centerLabel = sanitizeText(
    rawOption?.centerLabel || rawOption?.series?.[0]?.detail?.formatter,
    20,
    ""
  );
  return {
    tooltip: { trigger: "item" },
    legend: { bottom: 0 },
    series: [{
      type: "pie",
      radius: ["45%", "75%"],
      data,
      label: { show: false },
      ...(centerLabel ? {
        graphic: [{
          type: "text",
          left: "center",
          top: "center",
          style: { text: centerLabel, fontSize: 18, fontWeight: "bold", fill: "#1E293B" },
        }],
      } : {}),
    }],
  };
}

function validateChartSpec(input, fallbackTitle = "Your Health Data") {
  if (!input || typeof input !== "object") return fallbackChartSpec(fallbackTitle);

  const chart_type = SUPPORTED_CHART_TYPES.has(String(input.chart_type || "").toLowerCase())
    ? String(input.chart_type).toLowerCase()
    : "bar";

  const title = sanitizeText(input.title, MAX_TITLE, sanitizeText(fallbackTitle, MAX_TITLE, "Your Health Data"));
  const subtitle = sanitizeText(input.subtitle, MAX_SUBTITLE, "");
  const takeaway = sanitizeText(input.takeaway, MAX_TAKEAWAY, "");
  const suggested_follow_up = sanitizeFollowUps(input.suggested_follow_up || input.suggestedFollowUp);
  const rawOption = parseOption(input.option);

  let option = null;
  if (chart_type === "gauge") option = sanitizeGaugeOption(rawOption);
  else if (chart_type === "pie") option = sanitizePieOption(rawOption);
  else if (chart_type === "donut") option = sanitizeDonutOption(rawOption);
  else if (chart_type === "list_summary" || chart_type === "composed_summary") option = sanitizeListSummaryOption(rawOption, input);
  else if (chart_type === "heatmap") option = sanitizeHeatmapOption(rawOption);
  else if (chart_type === "radar") option = sanitizeRadarOption(rawOption);
  else if (chart_type === "boxplot") option = sanitizeBoxplotOption(rawOption);
  else if (chart_type === "candlestick") option = sanitizeCandlestickOption(rawOption);
  else if (chart_type === "treemap") option = sanitizeTreemapOption(rawOption);
  else option = sanitizeCartesianOption(rawOption, chart_type);

  if (!option) return fallbackChartSpec(title, takeaway || "I could not prepare that chart safely.");

  return {
    chart_type,
    title,
    subtitle,
    takeaway,
    highlight: input.highlight && typeof input.highlight === "object" ? input.highlight : null,
    suggested_follow_up,
    option: applyPremiumHealthTheme(option, { title, chartType: chart_type }),
  };
}

export { SUPPORTED_CHART_TYPES, fallbackChartSpec, validateChartSpec };
